-- Japanese national holidays 2026, 2027 from the Cabinet Office CSV
-- (https://www8.cao.go.jp/chosei/shukujitsu/syukujitsu.csv), generated by supabase/scripts/national-holidays.mjs.
-- Replaces the listed years, so a holiday the Cabinet Office moved or
-- removed does not linger.

delete from public.national_holiday
 where extract(year from date)::integer in (2026, 2027);

